inputs.content:
{
  "client": "星汉制造",
  "vendor": "铁锋重工",
  "project": "高炉控制系统维护",
  "mandate": {
    "response_time": {
      "baseline": "核心系统故障必须在2小时内远程响应，12小时内到达现场。",
      "walk_away_point": "响应时间超过24小时或到达时间超过24小时绝不接受。"
    },
    "fee_and_payment": {
      "baseline": "年度预算上限400万元。必须增加按季度考核的扣减机制，不接受无条件全额预付。",
      "walk_away_point": "超过450万且无任何考核机制绝不接受。"
    },
    "penalty": {
      "baseline": "违约金上限不超过合同总额的10%。乙方延迟到达的扣款上限应设定为当季费用的10%。",
      "walk_away_point": "违约金比例超过15%绝不接受。"
    },
    "intellectual_property": {
      "baseline": "基于甲方工艺数据和系统运行数据产生的优化方案及知识产权，必须归甲方所有，或至少由双方共有。",
      "walk_away_point": "绝不同意核心数据产生的知识产权单方面归乙方所有。"
    },
    "confidentiality": {
      "baseline": "保密期限3年即可。",
      "walk_away_point": "超过5年需特批。"
    },
    "liability_cap": {
      "baseline": "乙方累计赔偿总额不得低于合同总额的100%（即400万以上），或不低于甲方实际直接损失的150%。",
      "walk_away_point": "责任上限低于合同总额50%绝不接受。"
    },
    "dispute_resolution": {
      "baseline": "北京仲裁委员会仲裁，或北京市有管辖权的人民法院诉讼。",
      "walk_away_point": "不接受深圳管辖。"
    },
    "renewal": {
      "baseline": "必须提前60天书面通知，否则不自动续约。",
      "walk_away_point": "不接受自动续约条款。"
    }
  },
  "negotiation_strategy": "优先利用知识产权归属和付款条件作为筹码，换取响应时间的提升和费用的降低。"
}
